1	<script lang="ts">
2	  import { onDestroy } from 'svelte';
3	  import { todos, activeTimers, taskFilterStatus, taskFilterPriority, taskFilterTag, taskFilterDuePeriod, taskFilterGroupByTags, taskFilterSearch, taskFilterShowOther, taskFilterHideUngrouped, settings, activeProject, activeProjectTags, focusRequest, projectApplyTick } from '$lib/stores';
4	  import { api } from '$lib/api';
5	  import type { Todo, WorkSession } from '$lib/types';
6	  import { serializeAnnotations } from '$lib/taskAnnotations';
7	  import DatePicker from '$lib/components/DatePicker.svelte';
8	  import NotesEditor from '$lib/components/NotesEditor.svelte';
9	
10	  // ── Filter state (persisted in global stores) ─────────────────────────────
11	  let showFilters = $state(false);
12	  let searchInputEl: HTMLInputElement | null = $state(null);
13	
14	  // ── New-task form ─────────────────────────────────────────────────────────
15	  let showForm = $state(false);
16	  let newTitle = $state('');
17	  let newPriority: 'none' | 'high' | 'medium' | 'low' = $state('none');
18	  let newDue = $state('');
19	  let newTagInput = $state('');
20	
21	  // ── Edit state ────────────────────────────────────────────────────────────
22	  let editId: string | null = $state(null);
23	  let editTitle = $state('');
24	  let editPriority: 'none' | 'high' | 'medium' | 'low' = $state('none');
25	  let editDue = $state('');
26	  let editTagInput = $state('');
27	
28	  // ── Selection state ───────────────────────────────────────────────────────
29	  let selectedIds: Set<string> = $state(new Set());
30	  let confirmDelete = $state(false);
31	  let activeId: string | null = $state(null);
32	
33	  // ── Timer state ───────────────────────────────────────────────────────────
34	  let expandedSessions: string | null = $state(null);
35	  let editingSession: { todoId: string; index: number; start: string; end: string } | null = $state(null);
36	
37	  function toDatetimeLocal(iso: string): string {
38	    const d = new Date(iso);
39	    const pad = (n: number) => String(n).padStart(2, '0');
40	    return `${d.getFullYear()}-${pad(d.getMonth()+1)}-${pad(d.getDate())}T${pad(d.getHours())}:${pad(d.getMinutes())}`;
41	  }
42	
43	  async function saveSessionEdit(todo: Todo) {
44	    if (!editingSession || editingSession.todoId !== todo.id) return;
45	    const sessions = [...(todo.work_sessions ?? [])];
46	    sessions[editingSession.index] = {
47	      start: new Date(editingSession.start).toISOString(),
48	      end:   new Date(editingSession.end).toISOString(),
49	    };
50	    const updated = await api.saveTodo({ ...todo, work_sessions: sessions });
51	    todos.update((ts) => ts.map((t) => t.id === updated.id ? updated : t));
52	    editingSession = null;
53	  }
54	
55	  async function deleteSession(todo: Todo, index: number) {
56	    const sessions = (todo.work_sessions ?? []).filter((_, i) => i !== index);
57	    const updated = await api.saveTodo({ ...todo, work_sessions: sessions });
58	    todos.update((ts) => ts.map((t) => t.id === updated.id ? updated : t));
59	  }
60	  let tick = $state(0);
61	  let tickInterval: ReturnType<typeof setInterval> | null = null;
62	
63	  // ── Focus mode ────────────────────────────────────────────────────────────
64	  let focusMode = $state(false);
65	  let focusTodoId = $state<string | null>(null);
66	  let focusTodo = $derived(focusTodoId ? ($todos.find((t) => t.id === focusTodoId) ?? null) : null);
67	  // The currently-running ("live") task, if any — drives the header focus shortcut.
68	  let liveTodoId = $derived([...$activeTimers.keys()][0] ?? null);
69	
70	  // Auto-open the focus task's notes once when entering focus mode (or when the
71	  // focus task changes) — but don't fight the user if they then close them.
72	  let lastFocusOpenedId: string | null = null;
73	  $effect(() => {
74	    if (focusMode && focusTodo) {
75	      if (lastFocusOpenedId !== focusTodo.id) {
76	        lastFocusOpenedId = focusTodo.id;
77	        openNotes(focusTodo);
78	      }
79	    } else {
80	      lastFocusOpenedId = null;
81	    }
82	  });
83	
84	  // Honour a focus request coming from the sidebar (jump to the running task).
85	  $effect(() => {
86	    const reqId = $focusRequest;
87	    if (reqId && $todos.some((t) => t.id === reqId)) {
88	      focusTodoId = reqId;
89	      focusMode = true;
90	      focusRequest.set(null);
91	    }
92	  });
93	
94	  // Switching projects (the view stays mounted) should leave focus mode so the
95	  // newly-selected project's list is shown — the sidebar button jumps back in.
96	  let lastProjectId: string | null | undefined = undefined;
97	  $effect(() => {
98	    const pid = $activeProject?.id ?? null;
99	    if (lastProjectId !== undefined && pid !== lastProjectId) {
100	      focusMode = false;
101	      focusTodoId = null;
102	    }
103	    lastProjectId = pid;
104	  });
105	
106	  // Clicking a project in the sidebar always shows its full task list — leave
107	  // focus mode even when the already-active project is re-clicked (no id change).
108	  let lastApplyTick: number | undefined = undefined;
109	  $effect(() => {
110	    const tick = $projectApplyTick;
111	    if (lastApplyTick !== undefined && tick !== lastApplyTick) {
112	      focusMode = false;
113	      focusTodoId = null;
114	    }
115	    lastApplyTick = tick;
116	  });
117	
118	  // ── Notes state ───────────────────────────────────────────────────────────
119	  let notesOpenId: string | null = $state(null);
120	
121	  // ── Subtask state ─────────────────────────────────────────────────────────
122	  let addingChildFor: string | null = $state(null);
123	  let expandedChildren: Set<string> = $state(new Set());
124	  let newChildTitle = $state('');
125	
126	  $effect(() => {
127	    if ($activeTimers.size > 0) {
128	      if (!tickInterval) tickInterval = setInterval(() => { tick++; }, 1000);
129	    } else {
130	      if (tickInterval) { clearInterval(tickInterval); tickInterval = null; }
131	    }
132	  });
133	
134	  onDestroy(() => {
135	    if (tickInterval) clearInterval(tickInterval);
136	  });
137	
138	  // ── Derived ───────────────────────────────────────────────────────────────
139	  // Tags available to the page filter exclude the active project's prefilter tags:
140	  // those are already implied, so you can only filter/group by the remaining tags.
141	  let allTags = $derived(
142	    [...new Set($todos.flatMap((t) => t.tags))]
143	      .sort()
144	      .filter((tag) => tag !== 'other' && !$activeProjectTags.includes(tag))
145	  );
146	
147	  // Project tags that have leaked into the persisted group filter are ignored so the
148	  // prefilter tags never appear as group sections.
149	  let groupTags = $derived($taskFilterGroupByTags.filter((t) => !$activeProjectTags.includes(t)));
150	
151	  let filtered = $derived(
152	    $todos
153	      .filter((t) => {
154	        if (t.parent_id) return false; // children always appear under their parent
155	        // Project prefilter: only tasks carrying at least one project tag are in scope.
156	        if ($activeProjectTags.length > 0 && !$activeProjectTags.some((pt) => t.tags.includes(pt))) return false;
157	        if ($taskFilterStatus === 'pending' && t.done) return false;
158	        if ($taskFilterStatus === 'done' && !t.done) return false;
159	        if ($taskFilterPriority && t.priority !== $taskFilterPriority) return false;
160	        if ($taskFilterTag && !t.tags.includes($taskFilterTag)) return false;
161	        if (!$taskFilterShowOther && t.tags.includes('other')) return false;
162	        if ($taskFilterDuePeriod) {
163	          const due = t.due_date ? new Date(t.due_date) : null;
164	          const today = new Date(); today.setHours(0, 0, 0, 0);
165	          if ($taskFilterDuePeriod === 'overdue') {
166	            if (!due || due >= today) return false;
167	          } else if ($taskFilterDuePeriod === 'today') {
168	            const tomorrow = new Date(today); tomorrow.setDate(today.getDate() + 1);
169	            if (!due || due >= tomorrow) return false;
170	          } else if ($taskFilterDuePeriod === 'week') {
171	            const weekEnd = new Date(today); weekEnd.setDate(today.getDate() + 7);
172	            if (!due || due >= weekEnd) return false;
173	          } else if ($taskFilterDuePeriod === 'month') {
174	            const monthEnd = new Date(today); monthEnd.setDate(today.getDate() + 30);
175	            if (!due || due >= monthEnd) return false;
176	          }
177	        }
178	        if ($taskFilterSearch && !t.title.toLowerCase().includes($taskFilterSearch.toLowerCase())) return false;
179	        return true;
180	      })
181	      .sort((a, b) => {
182	        if (a.done !== b.done) return a.done ? 1 : -1;
183	        if (!a.due_date && !b.due_date) return 0;
184	        if (!a.due_date) return 1;
185	        if (!b.due_date) return -1;
186	        return a.due_date.localeCompare(b.due_date);
187	      })
188	  );
189	
190	  let pendingTodos = $derived(filtered.filter((t) => !t.done));
191	  let doneTodos = $derived(filtered.filter((t) => t.done));
192	  let rootTodoCount = $derived(
193	    $todos.filter((t) =>
194	      !t.parent_id &&
195	      ($activeProjectTags.length === 0 || $activeProjectTags.some((pt) => t.tags.includes(pt)))
196	    ).length
197	  );
198	
199	  let ungroupedPending = $derived(
200	    groupTags.length > 0
201	      ? pendingTodos.filter((t) => {
202	          if (groupTags.some((gt) => t.tags.includes(gt))) return false;
203	          // Always show tagless tasks; respect the toggle only for tasks that have tags not in the group.
204	          return t.tags.length === 0 || !$taskFilterHideUngrouped;
205	        })
206	      : []
207	  );
208	
209	  const priorityRank: Record<string, number> = { high: 0, medium: 1, low: 2, none: 3 };
210	
211	  let sortedGroups = $derived(
212	    groupTags
213	      .map((tag) => ({ tag, todos: pendingTodos.filter((t) => t.tags.includes(tag)) }))
214	      .filter((g) => g.todos.length > 0)
215	      .sort((a, b) => {
216	        const earliest = (ts: typeof pendingTodos) =>
217	          ts.reduce((min, t) => t.due_date ? Math.min(min, new Date(t.due_date).getTime()) : min, Infinity);
218	        const bestPrio = (ts: typeof pendingTodos) =>
219	          ts.reduce((best, t) => Math.min(best, priorityRank[t.priority] ?? 1), 2);
220	        const timeDiff = earliest(a.todos) - earliest(b.todos);
221	        return timeDiff !== 0 ? timeDiff : bestPrio(a.todos) - bestPrio(b.todos);
222	      })
223	  );
224	
225	  let selTodo = $derived(
226	    selectedIds.size === 1 ? $todos.find((t) => selectedIds.has(t.id)) ?? null : null
227	  );
228	
229	  // ── Actions ───────────────────────────────────────────────────────────────
230	  async function toggleDone(todo: Todo) {
231	    const nowMs = Date.now();
232	    const now = new Date(nowMs).toISOString();
233	    const markingDone = !todo.done;
234	
235	    if ($activeTimers.has(todo.id)) {
236	      const startMs = $activeTimers.get(todo.id)!;
237	      activeTimers.update((m) => { m.delete(todo.id); return m; });
238	      const session: WorkSession = { start: new Date(startMs).toISOString(), end: now };
239	      todo = { ...todo, work_sessions: [...(todo.work_sessions ?? []), session] };
240	    } else if (markingDone) {
241	      // Completing a task with no running timer still logs effort: a 1-minute
242	      // session ending at the moment it's marked done.
243	      const session: WorkSession = { start: new Date(nowMs - 60_000).toISOString(), end: now };
244	      todo = { ...todo, work_sessions: [...(todo.work_sessions ?? []), session] };
245	    }
246	
247	    const updated = await api.saveTodo({
248	      ...todo,
249	      done: markingDone,
250	      finished_at: markingDone ? now : null,
251	      started_at: !markingDone ? now : (todo.started_at ?? null),
252	    });
253	    todos.update((ts) => ts.map((t) => (t.id === updated.id ? updated : t)));
254	  }
255	
256	  async function startTimer(todo: Todo) {
257	    const now = new Date().toISOString();
258	    activeTimers.update((m) => { m.set(todo.id, Date.now()); return m; });
259	    if (!todo.started_at) {
260	      const updated = await api.saveTodo({ ...todo, started_at: now });
261	      todos.update((ts) => ts.map((t) => (t.id === updated.id ? updated : t)));
262	    }
263	  }
264	
265	  async function stopTimer(todo: Todo) {
266	    const startMs = $activeTimers.get(todo.id);
267	    if (!startMs) return;
268	    activeTimers.update((m) => { m.delete(todo.id); return m; });
269	
270	    const session: WorkSession = {
271	      start: new Date(startMs).toISOString(),
272	      end: new Date().toISOString(),
273	    };
274	    const updated = await api.saveTodo({
275	      ...todo,
276	      work_sessions: [...(todo.work_sessions ?? []), session],
277	      started_at: todo.started_at ?? session.start,
278	    });
279	    todos.update((ts) => ts.map((t) => (t.id === updated.id ? updated : t)));
280	  }
281	
282	  async function createTodo() {
283	    if (!newTitle.trim()) return;
284	    const typedTags = newTagInput.split(/[\s,]+/).map((t) => t.replace(/^#/, '').trim()).filter(Boolean);
285	    // Tasks created inside a project automatically carry its tags, so they stay in scope.
286	    const tags = [...new Set([...$activeProjectTags, ...typedTags])];
287	    const created = await api.saveTodo({
288	      id: '', title: newTitle.trim(), done: false, priority: newPriority,
289	      due_date: newDue || null, tags,
290	      created_at: new Date().toISOString(), updated_at: new Date().toISOString(),
291	    });
292	    todos.update((ts) => [created, ...ts]);
293	    newTitle = ''; newPriority = 'none'; newDue = ''; newTagInput = '';
294	    showForm = false;
295	  }
296	
297	  async function addChildTodo(parent: Todo) {
298	    if (!newChildTitle.trim()) return;
299	    const created = await api.saveTodo({
300	      title: newChildTitle.trim(),
301	      priority: parent.priority,
302	      tags: [...parent.tags],
303	      parent_id: parent.id,
304	    });
305	    todos.update((ts) => [...ts, created]);
306	    // Make sure the parent's subtask zone is expanded so the new child shows.
307	    expandedChildren = new Set(expandedChildren).add(parent.id);
308	    newChildTitle = '';
309	    addingChildFor = null;
310	  }
311	
312	  function startEdit(todo: Todo) {
313	    editId = todo.id;
314	    editTitle = todo.title;
315	    editPriority = todo.priority;
316	    editDue = todo.due_date ?? '';
317	    editTagInput = todo.tags.join(', ');
318	    selectedIds = new Set();
319	  }
320	
321	  async function saveEdit(todo: Todo) {
322	    const tags = editTagInput.split(/[\s,]+/).map((t) => t.replace(/^#/, '').trim()).filter(Boolean);
323	    const updated = await api.saveTodo({
324	      ...todo, title: editTitle.trim(), priority: editPriority,
325	      due_date: editDue || null, tags,
326	    });
327	    todos.update((ts) => ts.map((t) => (t.id === updated.id ? updated : t)));
328	    editId = null;
329	  }
330	
331	  async function deleteTodo(id: string) {
332	    activeTimers.update((m) => { m.delete(id); return m; });
333	    await api.deleteTodo(id);
334	    todos.update((ts) => ts.filter((t) => t.id !== id));
335	  }
336	
337	  function toggleSelect(id: string) {
338	    const next = new Set(selectedIds);
339	    if (next.has(id)) next.delete(id);
340	    else next.add(id);
341	    selectedIds = next;
342	    activeId = null;
343	    confirmDelete = false;
344	  }
345	
346	  async function deleteSelected() {
347	    for (const id of selectedIds) {
348	      await deleteTodo(id);
349	    }
350	    selectedIds = new Set();
351	    confirmDelete = false;
352	  }
353	
354	  function openNotes(todo: Todo) {
355	    notesOpenId = todo.id;
356	  }
357	
358	  function closeNotes() {
359	    notesOpenId = null;
360	  }
361	
362	  // ── Formatting helpers ────────────────────────────────────────────────────
363	  function priorityColor(p: string) {
