375	    const target = new Date(due);
376	    const days = Math.round((target.getTime() - today.getTime()) / 86400000);
377	    if (days === 0) return 'today';
378	    if (days === 1) return 'tomorrow';
379	    if (days === -1) return 'yesterday';
380	    if (days < 0) return `${Math.abs(days)}d ago`;
381	    if (days < 7) return `in ${days}d`;
382	    const weeks = Math.floor(days / 7);
383	    if (days < 28) return `in ${weeks}w`;
384	    const months = Math.floor(days / 30);
385	    return `in ${months}mo`;
386	  }
