399	  function formatElapsed(startMs: number): string {
400	    void tick;
401	    const secs = Math.floor((Date.now() - startMs) / 1000);
402	    const h = Math.floor(secs / 3600);
403	    const m = Math.floor((secs % 3600) / 60);
404	    const s = secs % 60;
405	    if (h > 0) return `${h}:${String(m).padStart(2, '0')}:${String(s).padStart(2, '0')}`;
406	    return `${m}:${String(s).padStart(2, '0')}`;
407	  }
