56	  // ── Theme ─────────────────────────────────────────────────────────────────
57	  function applyTheme(t: 'system' | 'light' | 'dark' | 'midnight' | 'forest') {
58	    const resolved = t === 'system'
59	      ? (window.matchMedia('(prefers-color-scheme: dark)').matches ? 'dark' : 'light')
60	      : t;
61	    document.documentElement.setAttribute('data-theme', resolved);
62	  }
