74	  // ── Data loading ──────────────────────────────────────────────────────────
75	  async function loadAll() {
76	    const [n, t, s, f, p] = await Promise.all([api.getNotes(), api.getTodos(), api.getSettings(), api.getFolders(), api.getProjects()]);
77	    notes.set(n);
78	    todos.set(t);
79	    settings.set(s);
80	    diskFolders.set(f);
81	    projects.set(p);
82	    const lastSync = await api.getLastSync();
83	    syncState.update((st) => ({ ...st, lastSync }));
84	    scheduleAutoSync(s.auto_sync, s.sync_interval_seconds);
85	  }
86	
87	  async function refreshNotesFromDisk() {
88	    const [fresh, folders] = await Promise.all([api.getNotes(), api.getFolders()]);
89	    diskFolders.set(folders);
90	    notes.update((current) => {
91	      const byId = new Map(current.map((n) => [n.id, n]));
92	      for (const n of fresh) {
93	        const existing = byId.get(n.id);
94	        if (!existing || n.updated_at > existing.updated_at) byId.set(n.id, n);
95	      }
96	      return [...byId.values()].sort(
97	        (a, b) => Number(b.pinned) - Number(a.pinned) || b.updated_at.localeCompare(a.updated_at)
98	      );
99	    });
100	  }
101	
102	  function scheduleAutoSync(enabled: boolean, intervalSecs: number) {
103	    if (autoSyncTimer) clearInterval(autoSyncTimer);
104	    if (!enabled || intervalSecs <= 0) return;
105	    autoSyncTimer = setInterval(triggerSync, intervalSecs * 1000);
106	  }
107	
108	  async function triggerSync() {
109	    syncState.update((s) => ({ ...s, syncing: true }));
110	    try {
111	      const result = await api.syncNow();
112	      const [n, t, f, p] = await Promise.all([api.getNotes(), api.getTodos(), api.getFolders(), api.getProjects()]);
113	      notes.set(n); todos.set(t); diskFolders.set(f); projects.set(p);
114	      // Only advance lastSync on success — a failed attempt must not be shown as
115	      // the last sync time.
116	      syncState.update((s) => ({ syncing: false, lastResult: result, lastSync: result.success ? result.timestamp : s.lastSync }));
117	    } catch {
118	      syncState.update((s) => ({ ...s, syncing: false }));
119	    }
120	  }
121	
122	  function handleKeydown(e: KeyboardEvent) {
123	    if (e.ctrlKey && e.key === 's') { e.preventDefault(); triggerSync(); }
124	  }
