126	  onMount(() => {
127	    loadAll().finally(() => { loading = false; });
128	    const onFocus = () => void refreshNotesFromDisk();
129	    const mq = window.matchMedia('(prefers-color-scheme: dark)');
130	    const onSystemChange = () => { if (get(theme) === 'system') applyTheme('system'); };
131	    window.addEventListener('keydown', handleKeydown);
132	    window.addEventListener('focus', onFocus);
133	    mq.addEventListener('change', onSystemChange);
134	    return () => {
135	      if (autoSyncTimer) clearInterval(autoSyncTimer);
136	      window.removeEventListener('keydown', handleKeydown);
137	      window.removeEventListener('focus', onFocus);
138	      mq.removeEventListener('change', onSystemChange);
139	    };
140	  });
