1	<script lang="ts">
2	  import { projects, activeProjectId, todos } from '$lib/stores';
3	  import { api } from '$lib/api';
4	  import type { Project } from '$lib/types';
5	  import {
6	    PROJECT_ICONS, PROJECT_COLORS, projectIconSvg,
7	    DEFAULT_PROJECT_ICON, DEFAULT_PROJECT_COLOR,
8	  } from '$lib/projectIcons';
9	
10	  let { collapsed = false, onApply }: {
11	    collapsed?: boolean;
12	    onApply: (project: Project) => void;
13	  } = $props();
14	
15	  // Move the modal to <body> so it escapes the mobile drawer's transform,
16	  // which would otherwise act as the containing block for position: fixed.
17	  function portal(node: HTMLElement) {
18	    document.body.appendChild(node);
19	    return { destroy() { if (node.parentNode) node.parentNode.removeChild(node); } };
20	  }
21	
22	  // ── Editor modal state ──────────────────────────────────────────────────────
23	  let editorOpen = $state(false);
24	  let editId = $state<string | null>(null); // null = creating new
25	  let fName = $state('');
26	  let fTags = $state<string[]>([]);
27	  let fIcon = $state(DEFAULT_PROJECT_ICON);
28	  let fColor = $state(DEFAULT_PROJECT_COLOR);
29	  let tagInput = $state('');
30	
31	  let allTags = $derived(
32	    [...new Set($todos.flatMap((t) => t.tags))].sort().filter((tag) => tag !== 'other')
33	  );
34	  let canSave = $derived(fName.trim().length > 0 && fTags.length > 0);
35	
36	  function openNew() {
37	    editId = null;
38	    fName = '';
39	    fTags = [];
40	    fIcon = DEFAULT_PROJECT_ICON;
41	    fColor = DEFAULT_PROJECT_COLOR;
42	    tagInput = '';
43	    editorOpen = true;
44	  }
45	
46	  function openEdit(p: Project, e: MouseEvent) {
47	    e.stopPropagation();
48	    editId = p.id;
49	    fName = p.name;
50	    fTags = [...p.tags];
51	    fIcon = p.icon || DEFAULT_PROJECT_ICON;
52	    fColor = p.color || DEFAULT_PROJECT_COLOR;
53	    tagInput = '';
54	    editorOpen = true;
55	  }
56	
57	  function closeEditor() { editorOpen = false; }
58	
59	  function toggleTag(tag: string) {
60	    fTags = fTags.includes(tag) ? fTags.filter((t) => t !== tag) : [...fTags, tag];
61	  }
62	
63	  function addTypedTags() {
64	    const parts = tagInput.split(/[\s,]+/).map((t) => t.replace(/^#/, '').trim()).filter(Boolean);
65	    for (const p of parts) if (!fTags.includes(p)) fTags = [...fTags, p];
66	    tagInput = '';
67	  }
68	
69	  async function persist(next: Project[]) {
70	    projects.set(next);
71	    await api.saveProjects(next);
72	  }
73	
74	  async function save() {
75	    if (!canSave) return;
76	    const name = fName.trim();
77	    if (editId) {
78	      await persist($projects.map((p) => p.id === editId
79	        ? { ...p, name, tags: [...fTags], icon: fIcon, color: fColor } : p));
80	    } else {
81	      const project: Project = {
82	        id: crypto.randomUUID(), name, tags: [...fTags], icon: fIcon, color: fColor,
83	      };
84	      await persist([...$projects, project]);
85	    }
86	    editorOpen = false;
87	  }
88	
89	  async function remove() {
90	    if (!editId) return;
91	    await persist($projects.filter((p) => p.id !== editId));
92	    if ($activeProjectId === editId) activeProjectId.set(null);
93	    editorOpen = false;
94	  }
95	</script>
96	
97	<div class="projects-section {collapsed ? 'collapsed' : ''}">
98	  {#if !collapsed}
99	    <div class="projects-header">
100	      <span class="projects-label">Projects</span>
101	      <button class="add-project-btn" onclick={openNew} title="New project" aria-label="New project">
102	        <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round"><line x1="12" y1="5" x2="12" y2="19"/><line x1="5" y1="12" x2="19" y2="12"/></svg>
103	      </button>
104	    </div>
105	  {/if}
106	
107	  {#each $projects as p (p.id)}
108	    <button
109	      class="project-item {$activeProjectId === p.id ? 'active' : ''}"
110	      onclick={() => onApply(p)}
111	      title={collapsed ? p.name : ''}
112	      style="--proj-color: {p.color}"
113	    >
114	      <span class="project-icon">
115	        {@html `<svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round">${projectIconSvg(p.icon)}</svg>`}
116	      </span>
117	      {#if !collapsed}
118	        <span class="project-name">{p.name}</span>
119	        <button class="project-edit-btn" onclick={(e) => openEdit(p, e)} title="Edit {p.name}" aria-label="Edit project">
120	          <svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M11 4H4a2 2 0 0 0-2 2v14a2 2 0 0 0 2 2h14a2 2 0 0 0 2-2v-7"/><path d="M18.5 2.5a2.121 2.121 0 0 1 3 3L12 15l-4 1 1-4 9.5-9.5z"/></svg>
121	        </button>
122	      {/if}
123	    </button>
124	  {/each}
125	
126	  {#if collapsed}
127	    <button class="project-item add-collapsed" onclick={openNew} title="New project" aria-label="New project">
128	      <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round"><line x1="12" y1="5" x2="12" y2="19"/><line x1="5" y1="12" x2="19" y2="12"/></svg>
129	    </button>
130	  {/if}
131	</div>
132	
133	{#if editorOpen}
134	<div use:portal>
135	  <div class="editor-backdrop" onclick={closeEditor} aria-hidden="true"></div>
136	  <div class="editor" role="dialog" aria-modal="true">
137	    <div class="editor-head">
138	      <h3>{editId ? 'Edit project' : 'New project'}</h3>
139	      <button class="editor-close" onclick={closeEditor} aria-label="Close">
