// ── Drag & drop: reparent + reorder subtasks ──────────────────────────────
let dragTodoId: string | null = $state(null);
let dropTargetId: string | null = $state(null);
let dropToRoot = $state(false);

function subOrder(t: Todo): number { return t.order ?? new Date(t.created_at).getTime(); }
function hasKids(id: string): boolean { return $todos.some((t) => t.parent_id === id); }
function clearDrag() { dragTodoId = null; dropTargetId = null; dropToRoot = false; }

function taskDragStart(e: DragEvent, todo: Todo) {
  dragTodoId = todo.id;
  if (e.dataTransfer) { e.dataTransfer.effectAllowed = 'move'; e.dataTransfer.setData('text/plain', todo.id); }
}
function taskDragOver(e: DragEvent, todo: Todo) {
  if (!dragTodoId || dragTodoId === todo.id || hasKids(dragTodoId)) return;
  e.preventDefault(); e.stopPropagation();
  if (e.dataTransfer) e.dataTransfer.dropEffect = 'move';
  dropTargetId = todo.id; dropToRoot = false;
}
async function reparentTo(todo: Todo, parentId: string | null, order?: number) {
  const updated = await api.saveTodo({ ...todo, parent_id: parentId, order: order ?? null });
  todos.update((ts) => ts.map((t) => t.id === updated.id ? updated : t));
  if (parentId) expandedChildren = new Set(expandedChildren).add(parentId);
}
async function taskDrop(e: DragEvent, target: Todo) {
  e.preventDefault(); e.stopPropagation();
  const draggedId = dragTodoId; clearDrag();
  if (!draggedId || draggedId === target.id) return;
  const dragged = $todos.find((t) => t.id === draggedId);
  if (!dragged || hasKids(draggedId)) return; // a task with subtasks can't be nested (one level only)
  if (target.parent_id) {
    // Drop onto a subtask → insert before it under the same parent (reorder / reparent-into).
    const parentId = target.parent_id;
    if (parentId === draggedId) return;
    const sibs = $todos.filter((t) => t.parent_id === parentId && t.id !== draggedId)
      .sort((a, b) => subOrder(a) - subOrder(b));
    const idx = sibs.findIndex((s) => s.id === target.id);
    const tOrd = subOrder(target);
    const prev = sibs[idx - 1];
    await reparentTo(dragged, parentId, prev ? (subOrder(prev) + tOrd) / 2 : tOrd - 1);
  } else {
    // Drop onto a top-level task → nest as its child at the end.
    if (dragged.parent_id === target.id) return;
    const kids = $todos.filter((t) => t.parent_id === target.id);
    await reparentTo(dragged, target.id, kids.reduce((m, k) => Math.max(m, subOrder(k)), 0) + 1);
  }
}
function rootDragOver(e: DragEvent) {
  if (!dragTodoId) return;
  const dg = $todos.find((t) => t.id === dragTodoId);
  if (!dg?.parent_id) return; // only a subtask can be promoted to top-level
  e.preventDefault();
  dropToRoot = true; dropTargetId = null;
}
async function rootDrop() {
  const draggedId = dragTodoId; const toRoot = dropToRoot; clearDrag();
  if (!draggedId || !toRoot) return;
  const dragged = $todos.find((t) => t.id === draggedId);
  if (dragged?.parent_id) await reparentTo(dragged, null);
}

