/* Floats above the header (fixed → no layout shift), visible only while dragging. */
.today-dropzone {
  position: fixed; top: 14px; left: 50%; transform: translateX(-50%); z-index: 100;
  display: flex; align-items: center; justify-content: center; gap: 8px;
  padding: 12px 22px; border-radius: 12px; white-space: nowrap;
  border: 2px dashed var(--accent); background: var(--accent-bg);
  color: var(--accent-lt); font-size: 0.85rem; font-weight: 600;
  box-shadow: 0 8px 24px rgba(0,0,0,0.25); pointer-events: auto;
}
.today-dropzone.over { background: var(--accent); color: #fff; transform: translateX(-50%) scale(1.03); }

/* Drag handle — the only draggable part of a row (keeps clicks clean). */
.drag-handle {
  position: absolute; left: 5px; top: 50%; transform: translateY(-50%);
  display: flex; align-items: center; justify-content: center; width: 12px;
  opacity: 0; cursor: grab; color: var(--text-7); z-index: 2; transition: opacity 0.12s;
}
.task-wrap:hover .drag-handle { opacity: 0.5; }
.drag-handle:hover { opacity: 1; }
.drag-handle:active { cursor: grabbing; }

