input.new_string:
/* Notes button on tasks that have notes — a full-height square flush to the row's
   right edge (negative margins cancel the card's padding). */
.notes-btn {
  flex-shrink: 0; align-self: stretch; aspect-ratio: 1;
  margin: -13px calc(-1 * var(--pad-x)) -13px 0;
  border: none; border-radius: 0;
  background: var(--accent-bg); color: var(--accent-lt); cursor: pointer;
  display: flex; align-items: center; justify-content: center;
  transition: background 0.12s, color 0.12s;
}
.notes-btn:hover { background: var(--accent-bg-2); color: var(--accent-ltr); }
.notes-btn.active { background: var(--accent); color: #fff; }
/* Subtask rows use tighter padding — match it so the square still sits flush. */
.children-zone .notes-btn { margin: -7px -10px -7px 0; }

